# Read once when the selector opens: our own assetOEE UDT instances (each asset's Line), whose tags aren't for picking, and
# every folder with a tag that can be picked somewhere below it (lower-case paths), so the tree doesn't show folders that
# would open empty. Only these folder paths are kept, not the tags themselves
hidden, folders = [], set()
for p in system.tag.browse('', {}).getResults() or []:
	provider = '[%s]' % str(p['name'])
	if provider.lower() in ['[system]', '[kanoames]', '[default]']: continue
	for r in system.tag.browse(provider, {'tagType': 'UdtInstance', 'recursive': True}).getResults() or []:
		if str(r.get('typeId') or '').lower() == 'kanoa/assetoee': hidden.append(str(r['fullPath']).lower() + '/')
	for r in system.tag.browse(provider, {'tagType': 'AtomicTag', 'recursive': True}).getResults() or []:
		low = str(r['fullPath']).lower()
		prov, rest = low.split(']', 1)
		parts = [s for s in rest.split('/') if s]
		if '_types_' in parts or low.startswith('[kanoa]kanoa/') or [h for h in hidden if low.startswith(h)]: continue
		path = prov + ']'
		folders.add(path)
		for part in parts[:-1]:
			path = path + ('' if path.endswith(']') else '/') + part
			folders.add(path)
return {'hidden': hidden, 'folders': sorted(folders)}
